// Bundles the remote screen viewer (noVNC) into one self-contained HTML file
// the app loads into a WebView, so no viewer code is fetched at runtime.
// Run `npm install && npm run build` here after changing src/ or upgrading
// @novnc/novnc, and commit the generated file.
import { writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const root = path.dirname(fileURLToPath(import.meta.url));
const output = path.resolve(root, "../../Sources/Heeler/Resources/RemoteScreenViewer.html");

const result = await build({
  bundle: true,
  entryPoints: [path.join(root, "src", "viewer.js")],
  // noVNC uses top-level await, so the bundle stays an ES module.
  format: "esm",
  legalComments: "none",
  logLevel: "warning",
  minify: true,
  target: "safari16",
  write: false,
});
const script = result.outputFiles[0].text.replaceAll("</script", "<\\/script");

// No network at all: every byte reaches noVNC through the app.
const html = `<!doctype html>
<!-- Generated by scripts/remote-screen-viewer/build.mjs from @novnc/novnc (MPL-2.0). Do not edit by hand. -->
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:">
<style>html,body,#screen{margin:0;width:100%;height:100%;overflow:hidden;background:transparent}</style>
</head>
<body><div id="screen"></div><script type="module">${script}</script></body>
</html>
`;

writeFileSync(output, html);
console.log(`[remote-screen-viewer] wrote ${path.relative(process.cwd(), output)} (${Math.round(html.length / 1024)} KB)`);
